/* Expanded, section-based prototype. All edits remain local and reversible. */
StudioModel.normalize(state);
const sectionFor=id=>state.sections.find(s=>s.id===id);
const activeSection=()=>sectionFor(selected);
const sectionKey=s=>StudioModel.sections[s.type]?.key||'section';
const sectionVariant=s=>s.variant||StudioModel.allowed(s.type,state.style)[0];
const sectionField=(s,k,label,type='text',hint='')=>field(label,'sectionprop.'+s.id+'.'+k,s.content[k]||'',type,hint);
const optionField=(s,k,label,values)=>selectField(label,'sectionoption.'+s.id+'.'+k,String(s.options[k]),values);
const inlineText=(s,key,tag='p',label='')=>`<${tag} contenteditable="true" data-section-edit="${s.id}:${key}" aria-label="${esc(label||key)}">${esc(s.content[key]||'')}</${tag}>`;
function socialLinks(){return (state.profile.socials||[]).filter(s=>StudioModel.safeUrl(s.url)).map(s=>`<a href="${esc(StudioModel.safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a>`).join('')}
function editable(text,tag,id,enabled,label=''){return `<${tag} ${enabled?`contenteditable="true" data-edit="${id}" aria-label="${esc(label||id)}"`:''}>${esc(text)}</${tag}>`}
function contentText(s,k,tag,edit){return edit?inlineText(s,k,tag):`<${tag}>${esc(s.content[k]||'')}</${tag}>`}
function portfolioSection(s,edit){
  const v=sectionVariant(s),p=state.profile,c=s.content,o=s.options,key=sectionKey(s);let html='';
  if(key==='hero'){
    const lines=state.headline.split('\n');html=`<div class="overline">${esc(p.title||'Your professional title')}</div><h1 ${edit?'contenteditable="true" data-edit="headline" aria-label="Portfolio headline"':''}>${esc(lines[0])}${lines.length>1?'<br><i>'+esc(lines.slice(1).join(' '))+'</i>':''}</h1><div class="hero-bottom">${editable(p.bio,'p','bio',edit,'Short introduction')}<div class="hero-details">${o.showAvailability&&p.availability?'<span class="availability">Available for select projects</span>':''}${o.showCta?btn(esc(o.cta||'View selected work'),'page:Work','pf-cta'):''}</div></div>${['Split','Visual'].includes(v)?`<div class="hero-media">${state.heroImage||state.projects[0]?.cover?`<img class="hero-image" src="${esc(state.heroImage||state.projects[0].cover)}" alt="${esc(state.heroImageAlt||'Featured creative work')}" ${edit?'data-action="choose-media:hero" role="button" tabindex="0" aria-label="Choose hero image"':''}>`:'<div class="image-empty">Choose an image that feels like you.</div>'}${edit?btn('Choose image','choose-media:hero','media-edit','image'):''}</div>`:''}`;
  }else if(key==='work'){
    const projects=state.projects.filter(p=>!['Archived','Hidden'].includes(p.status)&&(page==='Work'||p.featured));html=`<div class="pf-section-heading">${contentText(s,'title','h2',edit)}<span>${String(projects.length).padStart(2,'0')} PROJECTS</span></div>${c.description?contentText(s,'description','p',edit):''}<div class="project-grid">${projects.map(p=>projectCard(p,edit?'project:':'preview-project:')).join('')}</div>${!projects.length?`<div class="empty"><h3>Your best work goes here.</h3><p>Add a project when you’re ready. A few notes and a cover are enough.</p>${edit?btn('Add your first project','quick-add','primary','plus'):''}</div>`:''}`;
  }else if(key==='about'){
    html=`<div class="pf-section-heading">${contentText(s,'title','h2',edit)}<span>ABOUT</span></div><div class="about-composition">${v==='Portrait'?`<div class="about-portrait">${p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.photoAlt||p.name)}" ${edit?'data-action="choose-media:profile" role="button" tabindex="0" aria-label="Choose profile portrait"':''}>`:`<div class="portrait-placeholder"><span>${esc((p.name||'Your name').split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><p>Your perspective.<br>Your presence.</p></div>`}${edit?btn('Choose portrait','choose-media:profile','media-edit','image'):''}</div>`:''}<div class="about-copy">${editable(p.bio||'A little about you, in your own words.','p','bio',edit,'About biography')}<div class="about-meta"><span>${esc(p.location)}</span>${p.cv?`<a href="${p.cv.url}" download="${esc(p.cv.name)}">Download CV</a>`:''}</div>${socialLinks()?`<div class="pf-socials">${socialLinks()}</div>`:''}</div>${v==='Credentials'?`<div class="credentials"><span class="eyebrow">SPECIALTIES</span><div class="pf-tags">${p.skills.map(t=>`<span>${esc(t)}</span>`).join('')}</div><span class="eyebrow">TOOLS OF THE TRADE</span><div class="pf-tags">${p.tools.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div>`:''}</div>`;
  }else if(['services','experience','testimonials','clients'].includes(key)){
    html=`<div class="pf-section-heading">${contentText(s,'title','h2',edit)}<span>${key.toUpperCase()}</span></div>${c.description?contentText(s,'description','p',edit):''}<div class="section-items">${c.items.map((item,i)=>`<div class="section-item"><span class="item-number">${String(i+1).padStart(2,'0')}</span><div class="item-main"><h3>${esc(item.title)}</h3>${item.detail?`<p>${esc(item.detail)}</p>`:''}${item.meta?`<small>${esc(item.meta)}</small>`:''}</div></div>`).join('')||'<p>Add your first item to this section.</p>'}</div>`;
  }else if(key==='contact'){
    html=`<div class="contact-copy"><span class="eyebrow">LET’S TALK</span>${contentText(s,'title','h2',edit)}${contentText(s,'description','p',edit)}</div><div class="contact-links">${p.email?`<a class="contact-email" href="mailto:${esc(p.email)}">${esc(p.email)}</a>`:'<span class="help-tip">Add your contact email in the properties panel.</span>'}${p.availability?'<span class="availability">Open to new collaborations</span>':''}<div class="pf-socials">${socialLinks()}</div></div>`;
  }else if(key==='footer'){
    html=`${v==='Extended'?`<div class="footer-large"><h2>${esc(c.title)}</h2><div class="pf-socials">${socialLinks()}</div></div>`:''}<div class="footer-bottom"><span>© 2026 ${esc(p.name||'Your name')}</span><span>Made with Sitofolio</span></div>`;
  }
  const variantClass=v.toLowerCase().replaceAll(' ','-');return `<section class="pf-section pf-${key} layout-${variantClass} ${key==='hero'?(v==='Split'?'split':v==='Visual'?'visual':v==='Statement'?'statement':''):''} ${key==='work'?variantClass:''} ${edit?'selectable '+(selected===s.id?'selected':''):''}" ${edit?`data-section="${s.id}"`:""} data-hover="${o.hover==='None'?'none':'zoom'}" style="--work-columns:${Number(o.columns)||2};--work-ratio:${o.ratio==='Square'?'1':o.ratio==='Portrait'?'.8':'1.4'};--work-gap:${o.gap==='Compact'?'14px':o.gap==='Spacious'?'40px':'26px'}" ${edit?`tabindex="0" aria-label="Select ${esc(s.type)} section"`:''}>${edit&&selected===s.id?`<span class="selection-label">${esc(s.type)}</span>`:''}${html}</section>`;
}
portfolio=function(edit=false){StudioModel.normalize(state);const palette=state.palette==='ink'?['#111111','#f6f1e8']:['#f6f1e8','#111111'];const family={Minimal:'minimal',Editorial:'editorial',Bold:'bold',Cinematic:'cinematic',Gallery:'gallery','Clean Professional':'clean'}[state.style];let sections;
  if(page==='Home')sections=state.sections.filter(s=>!['About','Contact'].includes(s.type)||state.pageMode[s.type]!=='Dedicated page');else sections=state.sections.filter(s=>s.type===(page==='Work'?'Selected Work':page));
  const nav=['Work','About','Contact'];return `<article class="portfolio ${device} ${family} ${state.spacing.toLowerCase()} ${state.treatment.toLowerCase()} ${state.motion.toLowerCase()} ${state.typography==='Acumin only'?'sans':''}" style="--pf-bg:${palette[0]};--pf-text:${palette[1]};--pf-accent:${state.accent}"><nav class="pf-nav"><button class="pf-name" data-action="page:Home">${esc(state.profile.name||'Your name')}<span style="color:var(--pf-accent)">®</span></button><div class="pf-links">${nav.map(n=>`<button data-action="page:${n}">${n}</button>`).join('')}</div></nav>${sections.filter(s=>s.visible).map(s=>portfolioSection(s,edit)).join('')||`<div class="empty"><h2>A little room to create.</h2>${edit?btn('Add a section','add-section','primary'):''}</div>`}</article>`;
};
const originalFamily=applyFamily;
applyFamily=function(v){originalFamily(v);StudioModel.normalize(state);state.spacing=StudioModel.families[v].density;for(const s of state.sections){s.variant=StudioModel.allowed(s.type,v)[0]}state.heroVariant=StudioModel.allowed('Hero',v)[0];state.workVariant=StudioModel.allowed('Selected Work',v)[0]};
function variantPicker(s){return `<div class="variants section-variants">${StudioModel.allowed(s.type,state.style).map(v=>`<button class="variant ${sectionVariant(s)===v?'active':''}" data-action="section-variant:${s.id}:${v}" aria-pressed="${sectionVariant(s)===v}"><div class="layout-sketch sketch-${v.toLowerCase().replaceAll(' ','-')}"><span></span><span></span><span></span><span></span></div>${v}</button>`).join('')}</div>`}
function itemEditor(s){return `<div class="item-editor">${s.content.items.map((item,i)=>`<div class="item-edit"><div class="row between"><span class="eyebrow">ITEM ${i+1}</span>${ib('trash',`remove-item:${s.id}:${i}`,'Remove item '+(i+1))}</div>${field(s.type==='Testimonials'?'Quote':'Title',`item.${s.id}.${i}.title`,item.title,s.type==='Testimonials'?'textarea':'text')}${field(s.type==='Testimonials'?'Name':'Details',`item.${s.id}.${i}.detail`,item.detail||'')}${['Experience','Testimonials'].includes(s.type)?field(s.type==='Experience'?'Period':'Role / context',`item.${s.id}.${i}.meta`,item.meta||''):''}</div>`).join('')}${btn('Add item','add-item:'+s.id,'full','plus')}</div>`}
function globalProperties(){return `<div class="panel-block">${selectField('Style family','style',state.style,Object.keys(StudioModel.families))}<p class="help-tip">Switching family preserves your content and applies a compatible set of section layouts.</p></div><div class="panel-block">${selectField('Typography','typography',state.typography,['Editorial pairing','Acumin only'])}<p class="help-tip">Acumin Variable · Instrument Serif</p></div><div class="panel-block"><span class="eyebrow">COLOR PALETTE</span><div class="swatches"><button class="swatch ${state.palette==='ivory'?'active':''}" style="background:#f6f1e8" data-action="palette:ivory" aria-label="Warm ivory portfolio"></button><button class="swatch ${state.palette==='ink'?'active':''}" style="background:#111" data-action="palette:ink" aria-label="Ink black portfolio"></button></div><div style="margin-top:20px">${field('Accent color','accent',state.accent,'color')}</div></div><div class="panel-block">${selectField('Density','spacing',state.spacing,['Compact','Balanced','Spacious'])}${selectField('Image treatment','treatment',state.treatment,['Sharp','Rounded','Framed'])}${selectField('Motion','motion',state.motion,['None','Soft'])}</div>`}
editorRight=function(){const s=activeSection();let html='';if(!s)html=globalProperties();else if(propTab==='Design'){
  html=`<div class="panel-block"><span class="eyebrow">${esc(s.type)} LAYOUT</span>${variantPicker(s)}<p class="help-tip" style="margin-top:12px">Compatible with ${esc(state.style)}.</p></div>`;
  if(s.type==='Selected Work')html+=`<div class="panel-block">${optionField(s,'columns','Columns',['1','2','3'])}${optionField(s,'ratio','Image ratio',['Landscape','Square','Portrait'])}${optionField(s,'gap','Space between projects',['Compact','Balanced','Spacious'])}${optionField(s,'hover','Hover behavior',['None','Gentle zoom'])}</div>`;
  if(s.type==='Hero')html+=`<div class="panel-block"><label class="check-row"><input type="checkbox" data-option-check="${s.id}:showCta" ${s.options.showCta?'checked':''}>Show call to action</label>${s.options.showCta?field('Button label','sectionoption.'+s.id+'.cta',s.options.cta):''}<label class="check-row"><input type="checkbox" data-option-check="${s.id}:showAvailability" ${s.options.showAvailability?'checked':''}>Show availability</label>${['Split','Visual'].includes(sectionVariant(s))?btn('Choose hero image','choose-media:hero','full','image'):''}</div>`;
  if(['About','Contact'].includes(s.type))html+=`<div class="panel-block">${selectField('Where it lives','pagemode.'+s.type,state.pageMode[s.type],['Section on Home','Dedicated page'])}${s.type==='About'&&sectionVariant(s)==='Portrait'?btn('Choose portrait','choose-media:profile','full','image'):''}</div>`;
  html+=`<div class="panel-block">${btn('Edit content','prop:Content','full','type')}${btn('Global typography & colors','global','quiet full','settings')}</div>`;
}else{
  html='<div class="panel-block">';
  if(s.type==='Hero')html+=field('Headline','headline',state.headline,'textarea')+field('Professional title','profile.title',state.profile.title)+field('Introduction','profile.bio',state.profile.bio,'textarea');
  else if(s.type==='Selected Work')html+=sectionField(s,'title','Section title')+sectionField(s,'description','Introduction','textarea')+`<span class="eyebrow">FEATURED PROJECTS</span>${state.projects.filter(p=>p.status!=='Archived').map(p=>`<label class="check-row"><input type="checkbox" data-feature="${p.id}" ${p.featured?'checked':''}>${esc(p.title)}</label>`).join('')}${btn('Add project','quick-add','full','plus')}`;
  else if(s.type==='About')html+=sectionField(s,'title','Section title')+field('Biography','profile.bio',state.profile.bio,'textarea')+field('Location','profile.location',state.profile.location)+btn('Skills, links & CV','profile-details','full');
  else if(s.type==='Contact')html+=sectionField(s,'title','Headline')+sectionField(s,'description','Introduction','textarea')+field('Contact email','profile.email',state.profile.email,'email')+btn('Edit social links','profile-details','full');
  else if(s.type==='Footer')html+=sectionField(s,'title','Closing line')+field('Copyright name','profile.name',state.profile.name)+btn('Edit social links','profile-details','full');
  else html+=sectionField(s,'title','Section title')+sectionField(s,'description','Introduction','textarea')+itemEditor(s);
  html+='</div>';
}
return `<aside class="right-panel"><div class="prop-head"><h3>${esc(s?.type||'Global style')}</h3>${s?ib('more','section-options','Section actions'):icon('settings')}</div>${s?`<div class="panel-tabs">${['Design','Content'].map(t=>`<button class="${propTab===t?'active':''}" data-action="prop:${t}">${t}</button>`).join('')}</div>`:''}${html}</aside>`};
const updateOriginal=updateField;
updateField=function(id,value,rerender=true){const parts=id.split('.');if(['sectionprop','sectionoption','item','pagemode','social'].includes(parts[0])){mutate(()=>{if(parts[0]==='pagemode')state.pageMode[parts[1]]=value;else if(parts[0]==='social')state.profile.socials[Number(parts[1])][parts[2]]=value;else{const s=sectionFor(parts[1]);if(!s)return;if(parts[0]==='sectionprop')s.content[parts[2]]=value;if(parts[0]==='sectionoption')s.options[parts[2]]=value;if(parts[0]==='item')s.content.items[Number(parts[2])][parts[3]]=value}},rerender&&!$('#dialog').open);return}updateOriginal(id,value,rerender)};
function profileDetails(){const p=state.profile;modal('The person behind the work.',`<div class="profile-dialog"><div class="profile-photo-row">${p.photo?`<img src="${esc(p.photo)}" alt="Profile portrait">`:'<div class="avatar">'+esc((p.name||'?')[0])+'</div>'}<div>${btn('Choose portrait','choose-media:profile','','image')}<p class="help-tip">A photo is optional. Your work can lead.</p></div></div><div class="form-grid">${field('Name','profile.name',p.name)}${field('Professional title','profile.title',p.title)}${field('Location','profile.location',p.location)}${field('Email','profile.email',p.email,'email')}</div>${field('Biography','profile.bio',p.bio,'textarea')}<label class="check-row"><input type="checkbox" data-profile-available ${p.availability?'checked':''}>Available for new projects</label>${['skills','tools'].map(k=>`<div class="profile-list"><span class="eyebrow">${k.toUpperCase()}</span><div class="tag-list">${p[k].map((t,i)=>`<span>${esc(t)}${ib('close',`remove-tag:${k}:${i}`,'Remove '+t)}</span>`).join('')}</div><form data-tag-form="${k}" class="row"><input aria-label="New ${k==='skills'?'skill':'tool'}" name="tag" placeholder="${k==='skills'?'e.g. Editorial design':'e.g. After Effects'}" required maxlength="50"><button type="submit" class="btn">Add</button></form></div>`).join('')}<div class="profile-list"><span class="eyebrow">SOCIAL LINKS</span>${p.socials.map((s,i)=>`<div class="social-row">${field('Label','social.'+i+'.label',s.label)}${field('URL','social.'+i+'.url',s.url,'url')}${ib('trash','remove-social:'+i,'Remove social link '+(i+1))}</div>`).join('')}${btn('Add social link','add-social','','plus')}<p class="help-tip">Only valid http or https links appear in your portfolio.</p></div><div class="profile-list"><span class="eyebrow">CV / RÉSUMÉ</span>${p.cv?`<div class="row between"><a href="${p.cv.url}" download="${esc(p.cv.name)}">${esc(p.cv.name)}</a>${btn('Remove CV','remove-cv','quiet')}</div>`:''}<label class="field"><span>Upload PDF · up to 2 MB</span><input type="file" accept="application/pdf" data-cv-upload></label></div></div>`,btn('Done','close-dialog','primary'))}
let mediaTarget='';
function mediaPicker(target){mediaTarget=target;const all=[...state.projects.filter(p=>p.cover).map(p=>({name:p.title,url:p.cover})),...state.assets.filter(a=>a.url)];modal('Find the right image.',`<p class="muted">Reuse something from your library, or add a new image.</p><div class="asset-picker">${all.map((a,i)=>`<button class="asset-choice" data-action="use-media:${i}"><img src="${esc(a.url)}" alt="${esc(a.name)}"><span>${esc(a.name)}</span></button>`).join('')}</div><label class="upload-zone">${icon('upload')}<span>Upload image</span><input type="file" accept="image/png,image/jpeg,image/webp" data-media-upload><small>Up to 3 MB · stored in this browser</small></label>`,btn('Cancel','close-dialog','quiet'));}
function setMedia(url,name){mutate(()=>{if(mediaTarget==='hero'){state.heroImage=url;state.heroImageAlt=name}else if(mediaTarget==='profile'){state.profile.photo=url;state.profile.photoAlt=name}else if(mediaTarget==='cover'){getProject().cover=url}else if(mediaTarget.startsWith('block:')){getProject().blocks.find(b=>b.id===mediaTarget.split(':')[1]).image=url}else if(mediaTarget.startsWith('second:'))getProject().blocks.find(b=>b.id===mediaTarget.split(':')[1]).secondImage=url});closeModal();toast('Image updated.',true)}
let structurePlan=null,structureProjectId=null;
function reviewStructure(){const p=getProject();if(!p){toast('Add a project first.');return}structurePlan=StudioModel.plan(p,()=>crypto.randomUUID());structureProjectId=p.id;showPlan()}
function showPlan(){modal('A story to build on.',`<div class="row between"><span class="ai-dot">SIMULATED AI · REVIEW BEFORE ADDING</span><span class="small muted">${esc(getProject().type)}</span></div><p class="muted" style="margin:17px 0 24px">Your notes become the introduction. Prompts guide the rest, without inventing research or results.</p><div class="plan-blocks">${structurePlan.map((b,i)=>`<div class="plan-block"><div class="row between"><label class="check-row"><input type="checkbox" data-plan-check="${i}" ${b.include===false?'':'checked'}><strong>${esc(b.type)}</strong></label><div class="row">${ib('up','plan-move:'+i+':-1','Move suggested '+b.type+' up')}${ib('down','plan-move:'+i+':1','Move suggested '+b.type+' down')}</div></div>${!['Big Image','Image Grid / Gallery','Device / Mockup Showcase','Video Embed'].includes(b.type)?`<textarea aria-label="Suggested ${esc(b.type)}" data-plan-text="${i}">${esc(b.text)}</textarea>`:`<p class="help-tip">${b.type==='Video Embed'?'Add your video link after inserting.':'Uses your project cover. Replace it with project media later.'}</p>`}</div>`).join('')}</div><label class="field" style="margin-top:22px"><span>How should this join your existing story?</span><select id="plan-mode"><option value="missing">Add missing block types · keep existing content</option><option value="append">Append all selected blocks</option><option value="replace">Replace current blocks · undo available</option></select></label>`,btn('Cancel','close-dialog','quiet')+btn('Add reviewed blocks','apply-structure','ai'))}
const originalBlock=renderBlock;
renderBlock=function(b,p,edit=false){
  if(b.type==='Before & After'){const first=b.image||p.cover,second=b.secondImage||p.cover;return `<div class="comparison" style="--split:${b.split??50}%"><img src="${esc(second)}" alt="${esc(b.secondAlt||'After')}"><div class="before-layer"><img src="${esc(first)}" alt="${esc(b.alt||'Before')}"></div><span class="comparison-label before">Before</span><span class="comparison-label after">After</span><div class="comparison-line"></div></div><label class="comparison-control">Compare before and after<input type="range" min="0" max="100" value="${b.split??50}" data-compare="${b.id}" aria-label="Before and after comparison"></label>${edit?`<div class="row">${btn('Before image','choose-media:block:'+b.id,'quiet','image')}${btn('After image','choose-media:second:'+b.id,'quiet','image')}</div>`:''}`}
  if(b.type==='Device / Mockup Showcase')return `<div class="device-stage"><div class="device-browser"><div class="device-chrome"><span>● ● ●</span><span>${esc(p.title)}</span></div><img src="${esc(b.image||p.cover)}" alt="${esc(b.alt||p.title+' interface')}" ${edit?`data-action="choose-media:block:${b.id}" role="button" tabindex="0" aria-label="Choose showcase image"`:''}></div></div>`;
  if(b.type==='Video Embed'){const embed=StudioModel.videoEmbed(b.url||'');return `${embed?`<iframe class="video-frame" src="${embed}" title="${esc(p.title)} video" loading="lazy" allow="fullscreen; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`:`<div class="video-placeholder">${icon('image')}<p>${b.url?'Open the linked video to watch it.':'Your film belongs here.'}</p>${StudioModel.safeUrl(b.url)?`<a class="btn" target="_blank" rel="noopener" href="${esc(StudioModel.safeUrl(b.url))}">Watch video</a>`:''}</div>`}${edit?btn('Set video URL','video-url:'+b.id,'quiet'):''}`}
  return originalBlock(b,p,edit);
};
const oldOnboarding=onboarding;
onboarding=function(){const step=state.onboarding.step;if(step===0){return `<div class="onboarding"><header class="onboard-top">${logo()}${btn('Back to workspace','go:overview','quiet')}</header><main class="onboard-main"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>Start with your work.<br>Make it <i class="editorial">your own.</i></h1><p class="intro-copy">Explore the sample portfolio, or take the first steps with your own content.</p><div class="entry-options"><button class="entry-option" data-action="onboard-next"><span class="eyebrow">TAKE A LOOK AROUND</span><h2>Explore this workspace</h2><p>Keep the current profile and projects as you try the journey.</p><span>Continue with current work</span></button><button class="entry-option" data-action="start-empty"><span class="eyebrow">A FRESH PERSPECTIVE</span><h2>Start with my own work</h2><p>Only your name and title are required. Add the rest when it feels right.</p><span>Start a fresh draft</span></button></div><p class="help-tip" style="margin-top:20px">Your current workspace is saved separately so you can return to it.</p></main></div>`}
if(step===5&&!state.projects.length)return onboardingEmptyStep('Your best work goes here.','One project is a great start. You can also skip this and explore your portfolio first.',btn('Add your first project','quick-add','primary','plus'));
if(step===6&&!state.projects.length)return onboardingEmptyStep('Your words. Your pace.','You can use the writing assistant after adding a project. Your portfolio is ready to take shape.',btn('Choose my style','onboard-next','primary'));
return oldOnboarding()};
function onboardingEmptyStep(title,description,action){return `<div class="onboarding"><header class="onboard-top">${logo()}${btn('Back to workspace','go:overview','quiet')}</header><main class="onboard-main"><span class="eyebrow">MAKE IT YOURS · ${state.onboarding.step+1} / 8</span><h1>${title}</h1><p class="intro-copy">${description}</p>${action}</main><footer class="onboard-footer">${btn('Back','onboard-back','quiet')}<span class="help-tip">You can always add more later.</span>${btn('Skip for now','onboard-next','quiet')}</footer></div>`}
const oldRecommendations=recommended;
recommended=function(){const rec=oldRecommendations();const type=state.projects.find(p=>p.status!=='Archived')?.type;const family=type==='Photography'?'Gallery':['Motion','Video'].includes(type)?'Cinematic':type==='UI/UX'?'Clean Professional':null;if(family&&!rec.some(f=>f[0]===family))rec[2]=familyData.find(f=>f[0]===family);return rec};
let studioPanel='canvas';
const studioRenderOriginal=render;
render=function(){StudioModel.normalize(state);studioRenderOriginal();document.body.dataset.studioPanel=studioPanel;if(['editor','project'].includes(view)){
const names=view==='editor'?[['sections','Sections'],['canvas','Canvas'],['properties','Properties']]:[['sections','Story'],['canvas','Project'],['properties','Assistant']];app.insertAdjacentHTML('beforeend',`<nav class="mobile-studio-nav" aria-label="Editor panels">${names.map(([id,n])=>`<button data-action="studio-panel:${id}" aria-pressed="${studioPanel===id}" class="${studioPanel===id?'active':''}">${icon(id==='canvas'?'desktop':id==='sections'?'layers':'settings')}${n}</button>`).join('')}</nav>`)}
if(view==='editor'){$('.panel-foot')?.insertAdjacentHTML('afterbegin',`<button class="nav-row" data-action="profile-details">${icon('type')}Profile & links</button>`)}
if(view==='project'&&getProject()){$('.builder-canvas .case-heading')?.insertAdjacentHTML('beforeend',`<div class="row project-story-actions">${btn('Structure my notes','review-structure','ai','layers')}${btn('Choose cover from assets','choose-media:cover','quiet','image')}</div>`)}
if(['overview','onboarding'].includes(view)&&localStorage.getItem('sitofolio-workspace-backup')){$('.app-main,.onboard-main')?.insertAdjacentHTML('afterbegin',`<div class="restore-workspace row between"><span>You’re exploring a fresh draft.</span>${btn('Return to saved workspace','restore-workspace','quiet')}</div>`)}
};
const extraActionOriginal=handleExtraAction;
handleExtraAction=function(action,value){const parts=value.split(':');
  if(action==='section-variant'){mutate(()=>sectionFor(parts[0]).variant=parts.slice(1).join(':'));return}
  if(action==='add-item'){mutate(()=>sectionFor(value).content.items.push({title:'New item',detail:'',meta:''}));return}
  if(action==='remove-item'){mutate(()=>sectionFor(parts[0]).content.items.splice(Number(parts[1]),1));toast('Item removed.',true);return}
  if(action==='profile-details'||action==='account'){profileDetails();return}
  if(action==='remove-tag'){mutate(()=>state.profile[parts[0]].splice(Number(parts[1]),1));profileDetails();return}
  if(action==='add-social'){mutate(()=>state.profile.socials.push({label:'',url:''}));profileDetails();return}
  if(action==='remove-social'){mutate(()=>state.profile.socials.splice(Number(value),1));profileDetails();return}
  if(action==='remove-cv'){mutate(()=>state.profile.cv=null);profileDetails();return}
  if(action==='choose-media'){mediaPicker(value);return}
  if(action==='use-media'){const all=[...state.projects.filter(p=>p.cover).map(p=>({name:p.title,url:p.cover})),...state.assets.filter(a=>a.url)];const a=all[Number(value)];if(a)setMedia(a.url,a.name);return}
  if(action==='review-structure'||action==='ai'&&['structure','order'].includes(value)){reviewStructure();return}
  if(action==='plan-move'){const index=Number(parts[0]),to=Math.max(0,Math.min(structurePlan.length-1,index+Number(parts[1])));structurePlan.splice(to,0,structurePlan.splice(index,1)[0]);showPlan();return}
  if(action==='apply-structure'){const plan=structurePlan.filter(b=>b.include!==false).map(({include,...b})=>b),mode=$('#plan-mode').value;mutate(()=>{const p=state.projects.find(p=>p.id===structureProjectId);p.blocks=StudioModel.applyPlan(p.blocks,plan,mode)});closeModal();toast('Reviewed blocks added. Every word is editable.',true);return}
  if(action==='studio-panel'){studioPanel=value;document.body.dataset.studioPanel=value;document.querySelectorAll('.mobile-studio-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.action.endsWith(value));b.setAttribute('aria-pressed',String(b.dataset.action.endsWith(value)))});return}
  if(action==='start-empty'){try{if(!localStorage.getItem('sitofolio-workspace-backup'))localStorage.setItem('sitofolio-workspace-backup',JSON.stringify(state))}catch{toast('Not enough browser storage to preserve your workspace.');return}mutate(()=>{state=structuredClone(initial);state.profile={name:'',title:'',bio:'',email:'',location:'',skills:[],tools:[],socials:[],photo:'',cv:null};state.projects=[];state.assets=[];state.heroImage='';state.headline='Your work.\nYour point of view.';state.onboarding={role:'',goal:'',personality:[],step:1,complete:false};StudioModel.normalize(state)});return}
  if(action==='restore-workspace'){const saved=localStorage.getItem('sitofolio-workspace-backup');if(saved){mutate(()=>state=StudioModel.normalize(JSON.parse(saved)));localStorage.removeItem('sitofolio-workspace-backup');go('overview');toast('Your saved workspace is back.')}return}
  if(action==='onboard-next'){const o=state.onboarding;if(o.step===1&&!o.role){toast('Choose the kind of work you do.');return}if(o.step===2&&!o.goal){toast('Choose your main goal.');return}}
  if(action==='finish-onboard'){state.publish.seoTitle=state.profile.name+' — '+state.profile.title;state.publish.description=state.profile.bio;state.publish.slug=state.profile.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,30)||'my-portfolio'}
  if(action==='onboard-ai'){projectId=state.projects[0]?.id;reviewStructure();return}
  if(action==='page'&&view==='editor'){selected=state.sections.find(s=>s.type===(value==='Home'?'Hero':value==='Work'?'Selected Work':value))?.id;propTab='Design';render();return}
  if(action==='select'||action==='global'){studioPanel='properties';render();return}
  extraActionOriginal(action,value);
};
document.addEventListener('change',async e=>{const t=e.target;try{if(t.dataset.optionCheck){const [id,key]=t.dataset.optionCheck.split(':');mutate(()=>sectionFor(id).options[key]=t.checked)}if(t.hasAttribute('data-profile-available'))mutate(()=>state.profile.availability=t.checked,false);if(t.hasAttribute('data-plan-check'))structurePlan[Number(t.dataset.planCheck)].include=t.checked;if(t.hasAttribute('data-media-upload')){const file=t.files[0];if(!file)return;const url=await readImage(file);state.assets.push({name:file.name,url});setMedia(url,file.name)}if(t.hasAttribute('data-cv-upload')){const f=t.files[0];if(!f)return;if(f.type!=='application/pdf'||f.size>2*1024*1024)throw new Error('Choose a PDF smaller than 2 MB.');const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});mutate(()=>state.profile.cv={name:f.name,url});profileDetails();toast('CV saved in this browser.')}}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{const t=e.target;if(t.hasAttribute('data-plan-text'))structurePlan[Number(t.dataset.planText)].text=t.value;if(t.hasAttribute('data-compare')){const block=t.closest('.case-block');block?.querySelector('.comparison')?.style.setProperty('--split',t.value+'%')}});
document.addEventListener('focusout',e=>{const t=e.target;if(t.dataset.sectionEdit){const [id,key]=t.dataset.sectionEdit.split(':');mutate(()=>sectionFor(id).content[key]=t.innerText.trim(),false)}});
document.addEventListener('submit',e=>{const type=e.target.dataset.tagForm;if(type){e.preventDefault();const value=new FormData(e.target).get('tag').trim();if(value&&!state.profile[type].some(x=>x.toLowerCase()===value.toLowerCase()))mutate(()=>state.profile[type].push(value));profileDetails()}});
render();
